class SpendingLimitExceeded(Exception):
    pass

def check_spending_limit(agent_id, amount, window):
    """Raise if this action would push spend over the cap for the window."""
    spent_so_far = get_spend(agent_id, window)
    cap = get_cap(agent_id, window)
    if spent_so_far + amount > cap:
        raise SpendingLimitExceeded(
            f"{agent_id} would spend {spent_so_far + amount} against a {cap} cap for {window}"
        )
    record_spend(agent_id, amount, window)

def run_agent_loop(agent):
    while True:
        if not kill_switch_is_active(agent.id):
            log_event(agent.id, "stopped, kill switch is off")
            break

        action = agent.decide_next_action()
        check_spending_limit(agent.id, action.estimated_cost, window="hour")
        check_rate_limit(agent.id, window="minute")

        result = agent.execute(action)
        log_event(agent.id, action, result)
